  r->lokey=v[0];r->hikey=v[1];r->lovel=v[2];r->hivel=v[3];r->sample_rate=v[4];r->offset=v[5];r->end=(unsigned)v[6]+1;r->loop_start=v[7];r->loop_end=v[8];r->loop_mode=v[9];r->pitch_keycenter=v[10];r->pitch_keytrack=v[11];r->transpose=v[12];r->tune=v[13];r->prSeq=v[14];r->prPosition=v[15];r->prTrigger=v[16];r->prOneShot=v[17];r->attenuation=a[0];r->pan=a[1];r->ampenv.delay=r->ampenv.hold=0;r->ampenv.attack=a[2];r->ampenv.decay=a[3];r->ampenv.sustain=a[4];r->ampenv.release=a[5];if(version>=2){float x[5];int curve;if(!bank_read(fd,x,sizeof(x))||!bank_read(fd,&curve,4))goto bad;for(int j=0;j<5;j++)if(!isfinite(x[j])||x[j]<0||x[j]>(j==4?200:127))goto bad;if(x[0]>x[1]||x[2]>x[3]||curve<0||curve>3)goto bad;r->prXfinLo=x[0];r->prXfinHi=x[1];r->prXfoutLo=x[2];r->prXfoutHi=x[3];r->prRtDecay=x[4];r->prCurve=curve&1;r->prRtPresent=(curve&2)!=0;}
