  f->prMappingBytes=(pr_size)st.st_size;f->prMapping=mmap(0,f->prMappingBytes,PROT_READ,MAP_PRIVATE,fd,0);if(f->prMapping==MAP_FAILED){f->prMapping=0;goto bad;}f->fontSamples=(float*)((char*)f->prMapping+offset);
