static void bank_clear_context(tsf*b){if(!b)return;memset(b->prRelease,0,sizeof(b->prRelease));memset(b->prPendingHead,0,sizeof(b->prPendingHead));memset(b->prAttackCount,0,sizeof(b->prAttackCount));memset(b->prAttackHead,0,sizeof(b->prAttackHead));b->prOffValid=0;}
static int bank_take_attack(tsf*b,int key,unsigned*group,float*velocity,float*age){if(!b->prBank||key<0||key>127||!b->prAttackCount[key])return 0;unsigned h=b->prAttackHead[key];*group=b->prAttack[key][h].group;*velocity=b->prAttack[key][h].velocity;*age=(float)(b->prSeconds-b->prAttack[key][h].at);b->prAttackHead[key]=(h+1)&31;b->prAttackCount[key]--;return 1;}
static int bank_region_match(tsf*f,struct tsf_region*r,int key,int vel){if(pr_region_gain(f,r,key,vel)<=0||!pr7_matches(f,r,-1))return 0;if(!f->prBank)return 1;return r->prTrigger==f->prTrigger&&(r->prSeq<=1||f->prSeqCounters[r-f->presets[0].regions]%r->prSeq==r->prPosition-1);}
/* Original per-note velocity and rendered duration survive repeats under pedal. */
static void bank_trigger_context(tsf*b,int key,int trigger,float velocity,float age,float energy){if(!b||!b->prBank||key<0||key>127||velocity<=0)return;b->prTrigger=trigger;b->prTriggerAge=age;b->prTriggerEnergy=energy;tsf_channel_note_on(b,0,key,velocity/127.0f);b->prTrigger=0;}
static void bank_trigger(tsf*b,int key,int trigger){if(b&&key>=0&&key<128)bank_trigger_context(b,key,trigger,b->prVelocity[key],0,1);}
static void bank_defer(tsf*b,int key,float velocity,float age,float energy){unsigned count=b->prRelease[key],head=b->prPendingHead[key];if(count==32){head=(head+1)&31;b->prPendingHead[key]=head;count--;}unsigned i=(head+count)&31;b->prPending[key][i].velocity=velocity;b->prPending[key][i].age=age;b->prPending[key][i].energy=energy;b->prPending[key][i].at=b->prSeconds;b->prRelease[key]=count+1;}
static void bank_release_pending(tsf*b,int key){unsigned count=b->prRelease[key],head=b->prPendingHead[key];for(unsigned n=0;n<count;n++){unsigned i=(head+n)&31;float elapsed=(float)(b->prSeconds-b->prPending[key][i].at);float age=b->prPending[key][i].age+elapsed,energy=b->prPending[key][i].energy;bank_trigger_context(b,key,1,b->prPending[key][i].velocity,age,energy);}b->prRelease[key]=b->prPendingHead[key]=0;}
